        name.pack_start(label("NEXUM", "nv-titulo", "nv-nexum"), False, False, 0)
        name.pack_start(label("Dev Stack", "nv-titulo", "nv-marca"), False, False, 0)
        t.pack_start(name, False, False, 0)
